userscript.function:

            $share.editor = { 
                frame:$(layoutObj.cells('a').cell).find('.dhx_cell_cont_layout')[0].appendChild($('<iframe class="contract-editor-frame" style="width:100%;height:100%;border:0px;padding:0px;margin:0px;"></iframe>')[0])
            }

            if(Sepoa.request.isPopup && $sObject._vp.parents('.sepoaux.screen_area').length <= 0){
            	if (Sepoa.request.NEW_FLAG) {
            		var config = {
            			module:{
            				WORK_TYPE : Sepoa.request.SMR_STATUS == 'T' || Sepoa.request.SMR_STATUS == 'R' || Sepoa.request.SMR_STATUS == 'F' || Sepoa.request.SMR_STATUS == 'N' ? 'T' : 'C',
	                        CONT_MODULE : (Sepoa.request.SMR_STATUS == 'T' || Sepoa.request.SMR_STATUS == 'R' || Sepoa.request.SMR_STATUS == 'F' || Sepoa.request.SMR_STATUS == 'N') && Sepoa.request.REAL_FLAG != 1 ? 'EDITOR' : 'VIEW',
	                        MODE : Sepoa.request.SMR_STATUS == 'T' ? 'NONE' : 'COMPLETE',
	                        SMR_STATUS : Sepoa.request.SMR_STATUS,
	                        REAL_FLAG : Sepoa.request.REAL_FLAG,
	                        NEW_FLAG : Sepoa.request.NEW_FLAG
            			},
            			document: {
            				DOC_DATA : {
            					PATH : Sepoa.request.PATH,
            					SELECT_SEAL_LIST : Sepoa.request.SELECT_SEAL_LIST
            				}
            			},
            			editor : {}
            		}
            	} else {
	            	if (Sepoa.request.DOC_DATA) {
		            	var docData = Sepoa.request.DOC_DATA.replaceAll('&#34;', '"');
	            	} else {
	            		var docData = JSON.stringify({
			                SMR_NUMBER: Sepoa.request.SMR_NUMBER,
			                SMD_NUMBER: Sepoa.request.SMD_NUMBER,
			                TARGET : Sepoa.request.TARGET
			            });
	            	}
	                var config = {
	                    module:{
	                        WORK_TYPE : Sepoa.request.SMR_STATUS == 'T' || Sepoa.request.SMR_STATUS == 'R' || Sepoa.request.SMR_STATUS == 'F' || Sepoa.request.SMR_STATUS == 'N' ? 'T' : 'C',
	                        CONT_MODULE : (Sepoa.request.SMR_STATUS == 'T' || Sepoa.request.SMR_STATUS == 'R' || Sepoa.request.SMR_STATUS == 'F'|| Sepoa.request.SMR_STATUS == 'N' )&& Sepoa.request.REAL_FLAG != 1 && Sepoa.request.VIEW_MODE_CHK !='VIEW' ? 'EDITOR' : 'VIEW', 
	                        MODE : Sepoa.request.SMR_STATUS == 'T' || Sepoa.request.SMR_STATUS == 'R' || Sepoa.request.SMR_STATUS == 'F' ? 'NONE' : 'COMPLETE',
	                        SMR_STATUS : Sepoa.request.SMR_STATUS,
	                        REAL_FLAG : Sepoa.request.REAL_FLAG
	                    },
	                    document : {
	                        DOC_DATA : JSON.parse(docData)
	                    },
	                    editor:{}
	                }
	            }
                doOpenDocument(config);
            }else {
                callFunction('p', 'childScreenReady', [{
                    name:"MODULE",
                    id: $sObject.aliasCode,
                    fn:{
                        doOpenDocument:doOpenDocument,
                        doUpdateShare:doUpdateShare,
                        doClear:doClear
                    }
                }])
            }


            $share.config = config;
            if("T" == config.module.WORK_TYPE){
            	if("EDITOR" == config.module.CONT_MODULE){//임시저장, 전자
                    config.editor.header=[
                        {
                            type:'button',
                            position:'float',
                            list:[
                                {id:"SAVE"  , text:"{BUTTON.save}"  	, type:"save"   	, onclick:function(){onButtonClick('SAVE')}},
                                {id:"DELETE", text:"{BUTTON.delete}"	, type:"delete"		, onclick:function(){onButtonClick('DELETE')}}
                            ]
                        }
                    ]
             	} else if(Sepoa.request.VIEW_MODE_CHK !='VIEW' && "VIEW" == config.module.CONT_MODULE && "R" == config.module.SMR_STATUS){
             		//반려 ,수정버튼클릭시, 실물
             		config.editor.header=[
                        {
                            type:'button',
                            position:'float',
                            list:[
                                {id:"IN"	, text:"{BUTTON.ZOOM_IN}"	, type:"default"   	, onclick:function(){onButtonClick('IN')}},
                                {id:"OUT"	, text:"{BUTTON.ZOOM_OUT}"	, type:"default"   	, onclick:function(){onButtonClick('OUT')}},
                                {id:"DELETE", text:"{BUTTON.delete}"	, type:"delete"		, onclick:function(){onButtonClick('DELETE')}},
                                {id:"CLOSE"	, text:"{BUTTON.close}"		, type:"back"   	, onclick:function(){onButtonClick('CLOSE')}}
                            ]
                        }
                    ]
             	} else {
             		config.editor.header=[
                        {
                            type:'button',
                            position:'float',
                            list:[
                                {id:"IN"	, text:"{BUTTON.ZOOM_IN}"	, type:"default"   	, onclick:function(){onButtonClick('IN')}},
                                {id:"OUT"	, text:"{BUTTON.ZOOM_OUT}"	, type:"default"   	, onclick:function(){onButtonClick('OUT')}},
                                {id:"CLOSE"	, text:"{BUTTON.close}"		, type:"back"   	, onclick:function(){onButtonClick('CLOSE')}}
                            ]
                        }
                    ]
             	}
            } else if("VIEW" == config.module.CONT_MODULE && "C" != config.module.SMR_STATUS){//결재진행중,반려,승인,
        		config.editor.header=[
                    {
                        type:'button',
                        position:'float',
                        list:[
                            {id:"IN"	, text:"{BUTTON.ZOOM_IN}"	, type:"default"   	, onclick:function(){onButtonClick('IN')}},
                            {id:"OUT"	, text:"{BUTTON.ZOOM_OUT}"	, type:"default"   	, onclick:function(){onButtonClick('OUT')}},
                            {id:"CLOSE"	, text:"{BUTTON.close}"		, type:"back"   	, onclick:function(){onButtonClick('CLOSE')}}
                        ]
                    }
                ]
            } else if("EDITOR" == config.module.CONT_MODULE && "R" == config.module.SMR_STATUS){//반려의 수정
            	config.editor.header=[
                    {
                        type:'button',
                        position:'float',
                        list:[
                            {id:"IN"	, text:"{BUTTON.ZOOM_IN}"	, type:"default"   	, onclick:function(){onButtonClick('IN')}},
                            {id:"OUT"	, text:"{BUTTON.ZOOM_OUT}"	, type:"default"   	, onclick:function(){onButtonClick('OUT')}},
                            {id:"DELETE", text:"{BUTTON.delete}"	, type:"delete"		, onclick:function(){onButtonClick('DELETE')}},
                            {id:"CLOSE"	, text:"{BUTTON.close}"		, type:"back"   	, onclick:function(){onButtonClick('CLOSE')}}
                        ]
                    }
                ]
            } else {
            	if("C" == config.module.SMR_STATUS){
            		if (Sepoa.request.LINK == 'QR') {	// QR코드로 들어온 경우엔 다운로드 없음
	            		config.editor.header=[
	                        {
	                            type:'button',
	                            position:'float',
	                            list:[
	                                {id:"IN"	, text:"{BUTTON.ZOOM_IN}"	, type:"default"   	, onclick:function(){onButtonClick('IN')}},
	                                {id:"OUT"	, text:"{BUTTON.ZOOM_OUT}"	, type:"default"   	, onclick:function(){onButtonClick('OUT')}},
	                                {id:"CLOSE"	, text:"{BUTTON.close}"		, type:"back"   	, onclick:function(){onButtonClick('CLOSE')}}
	                            ]
	                        }
	                    ]
            		} else {
	            		config.editor.header=[
	                        {
	                            type:'button',
	                            position:'float',
	                            list:[
	                                {id:"DOWNLOAD"	, text:"{BUTTON.download}"	, type:"secondary"	, onclick:function(){onButtonClick('DOWNLOAD')}},
	                                {id:"IN"	, text:"{BUTTON.ZOOM_IN}"	, type:"default"   	, onclick:function(){onButtonClick('IN')}},
	                                {id:"OUT"	, text:"{BUTTON.ZOOM_OUT}"	, type:"default"   	, onclick:function(){onButtonClick('OUT')}},
	                                {id:"CLOSE"	, text:"{BUTTON.close}"		, type:"back"   	, onclick:function(){onButtonClick('CLOSE')}}
	                            ]
	                        }
	                    ]
            		}
            	}
            }


            if(id == "SAVE"){
                if(!$share.editor.fn.doUpdateShare(id)){
                    return;
                }
                doDocumentUpdate((id == "SAVE")?"MODULE":"END");
            } else if(id == "DELETE") {
            	doDelete();
            } else if(id == "CLOSE") {
	            	doCloseEnd();
            } else if(id == "IN" || id == "OUT") {
                doZoom(id);   
            } else if(id == "DOWNLOAD") {
                doDownload();
            } else if(id == "PRINT") {
                doPrint();
            }


	if(Sepoa.request.isPopup && Sepoa.request.isRealPopup){
        if(!Sepoa.request.onLink){
            window.close();
        }else{
            document.location.reload();
        }
    }else if(Sepoa.request.isPopup){
        selfObj.close();
    }else{
        doClear();
        callFunction('p', 'changeView', [{view:'LIST'}])
    }


 var config = {
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    on:{
        callback:function(res, config, params){
            if(res.flag){

            }else{
            	console.log(arguments);
                Alert(Sepoa.cache.text.get('POA_CONTRACT.STATUS_' + res.status));
            }
        }
    }
}
var params = {
    module:"seal"+(Sepoa.config.get('sepoa.seal.process') || "")+".req",
    action: "doDocumentDownload",
    KEY : $share.config.document.DOC_DATA.SMR_NUMBER + "_" + ($share.config.document.DOC_DATA.SMD_NUMBER || $share.config.document.DOC_DATA.SD_NUMBER),
    SMR_NUMBER : $share.config.document.DOC_DATA.SMR_NUMBER,
    SMD_NUMBER : $share.config.document.DOC_DATA.SMD_NUMBER,
    SD_NUMBER : $share.config.document.DOC_DATA.SD_NUMBER,
    TARGET : $share.config.document.DOC_DATA.TARGET
}

sUtils.multipart.download(config, params);


        	const height = (SUX.getModuleTop().innerHeight - 40) * 0.95;
        	const width = (SUX.getModuleTop().innerWidth) * 0.8;

            sUtils.popup.modal({
                url: window.CONTEXT_NAME + '/UxDefault/Common/PDFViewer.sux',
                params: {
                    PROCESS_ID: "sepoa.svc.seal.SepoaReqSealService",
                    METHOD: "doDocumentPrint",
					KEY : $share.config.document.DOC_DATA.SMR_NUMBER + "_" + ($share.config.document.DOC_DATA.SMD_NUMBER || $share.config.document.DOC_DATA.SD_NUMBER),
					SMR_NUMBER : $share.config.document.DOC_DATA.SMR_NUMBER,
					SMD_NUMBER : $share.config.document.DOC_DATA.SMD_NUMBER,
					SD_NUMBER : $share.config.document.DOC_DATA.SD_NUMBER,
					TARGET : $share.config.document.DOC_DATA.TARGET
                },
                height:height,
                width:width,
                title: Sepoa.cache.text.get('BUTTON.print2')
            });
            return;


        	var seals = $share.config.document.DOC_DATA.SELECT_SEAL_LIST[0];
        	var editor_htmls = $share.config.document.EDITOR_HTMLS;
        	var items_list = callFunction('CT_503', 'getItemsList', []);
        	var markObj = {};
           	var allMarkCount = 0;


            //날인인감 개수 설정
            for (var i=0; i<editor_htmls.length; i++) {          	
            	var pos = 0;
            	//공통인감 설정
            	while (true) {
            		pos = editor_htmls[i].FIX_HTML.indexOf('contract-item-box-seal-code-CI', pos);
					if (pos == -1)
						break;

					var manage_number = editor_htmls[i].FIX_HTML.substr(pos+28, 13);
					if (markObj[manage_number] == undefined) {
						markObj[manage_number] = 0;
					}
					markObj[manage_number]++;
					allMarkCount++;
					pos += 13;
            	}

            	//사용인감 설정
            	pos = 0;
				while (true) {
					pos = editor_htmls[i].FIX_HTML.indexOf('contract-item-box-seal-code-SLM', pos);
					if (pos == -1)
						break;

					var manage_number = editor_htmls[i].FIX_HTML.substr(pos+28, 15);
					if (markObj[manage_number] == undefined) {
						markObj[manage_number] = 0;
					}
					markObj[manage_number]++;
					allMarkCount++;
					pos += 15;
				}
            }


            // 법인인감만 있는 경우면 통털어 하나라도 썼는지 체크
            // 그외엔 모든 사용인감을 사용했는지 체크
            var sealTypeAllArr = seals.map(function(seal, index, array) { return seal.SEAL_TYPE; });
            const sealTypeSet = new Set(sealTypeAllArr);
            const sealTypeArr = [...sealTypeSet];

            if (sealTypeArr.length == 1 && sealTypeArr[0] == 'C') {	// 법인인감 뿐이면
            	const sealArr = seals.filter(function(seal, idx, arr) { return markObj[seal.MANAGE_NUMBER] });
            	if (sealArr.length == 0) {
            		Alert(Sepoa.cache.text.get('CT_502_L.NOT_SEAL_USED'));
            		return;
            	}
            } else {
	            //사용인감을 1개라도 1번 이상 사용하지 않았을 경우 오류메시지
	            for (var i=0; i < seals.length; i++) {
	            	if (seals[i].SEAL_TYPE != 'C' && !markObj[seals[i].MANAGE_NUMBER]) {
	            		Alert(Sepoa.cache.text.get('CT_502_L.NOT_SEAL_USED'));
	            		return;
	            	}
	            }
            }

            /*
            //사용인감을 1개라도 1번 이상 사용하지 않았을 경우 오류메시지
            for (var i=0; i<seals.length; i++) {
            	var seal = seals[i];
            	if (!(items_list.TOTAL[seal.SEAL_TYPE] && items_list.TOTAL[seal.SEAL_TYPE].length)) {
            		Alert(Sepoa.cache.text.get('CT_502_L.NOT_SEAL_USED'));
            		return;
            	}
            }
            */
            var config = {
                url:window.CONTEXT_NAME+'/SepoaActionController.sux',
                on:{
                    callback:function(res, config, params){
                        if(res.flag){
                            Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0001'), function(){
                            	Sepoa.params.setMarkCount(JSON.stringify(markObj).replace(/\"/gi, '~REPTOQM~'), allMarkCount);
                                doCloseEnd();
                            });
                        }else{
                            Alert(res.message);
                        }
                    }
                },
                contentType:"json"
            }

            var params = {
                module:"seal"+(Sepoa.config.get('sepoa.seal.process') || "")+".req",
                action: "doDocumentUpdate",
                SMR_NUMBER : $share.config.document.DOC_DATA.SMR_NUMBER,
                SMD_NUMBER : $share.config.document.DOC_DATA.SMD_NUMBER,
                NEXT_STEP: nextStep
            }

            switch(nextStep){
            case "MODULE":
            case "END":
                params.EDITOR_HTMLS=$share.config.document.EDITOR_HTMLS;
                params.DOC_INFO_DATA=$share.config.document.DOC_INFO_DATA;
                break;
            }

            sUtils.multipart.send(config, params);


        	Confirm(Sepoa.cache.text.get('MESSAGE.1015'), function(result) {
        		if (result) {
		        	var config = {
		                url:window.CONTEXT_NAME+'/SepoaActionController.sux',
		                on:{
		                    callback:function(res, config, params){
		                        if(res.flag){
		                        	Sepoa.params.deleteDoc();
		                        	Alert(Sepoa.cache.text.get('MESSAGE.5107'));
		                            doCloseEnd();
		                        }else{
		                            Alert(Sepoa.cache.text.get('POA_CONTRACT.STATUS_' + res.status));
		                        }
		                    }
		                }
		            }

		            var params = {
		                module:"seal"+(Sepoa.config.get('sepoa.seal.process') || "")+".req",
		                action: "doDeleteDocumentFile",
		                KEY : $share.config.document.DOC_DATA.SMR_NUMBER + "_" + ($share.config.document.DOC_DATA.SMD_NUMBER || $share.config.document.DOC_DATA.SD_NUMBER),
		                SMR_NUMBER : $share.config.document.DOC_DATA.SMR_NUMBER,
		                SMD_NUMBER : $share.config.document.DOC_DATA.SMD_NUMBER,
		                SD_NUMBER : $share.config.document.DOC_DATA.SD_NUMBER,
		                TARGET : $share.config.document.DOC_DATA.TARGET
		            }

		            sUtils.multipart.send(config, params);
		    	}
            });
